#[allow(unused_variables)] fn ability_0_0_0_keyword(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); if Some(asker.source).is_some_and(|candidate: ObjectId| q.state().battlefield().iter().any(|&a| q.state().obj(a).attached_to == Some(candidate) && q.chars(a).has_subtype(Subtype::Aura))) { chars.keywords = chars.keywords.with(Keyword::CantBeBlocked); } }

